type TransferState =
  | { step: 'edit'; amount: string; error?: string }
  | { step: 'confirm'; amount: number }
  | { step: 'submitting'; amount: number }
  | { step: 'done'; reference: string };

type Action =
  | { type: 'amountChanged'; value: string }
  | { type: 'review' }
  | { type: 'submit' }
  | { type: 'succeeded'; reference: string }
  | { type: 'back' };

function reducer(s: TransferState, a: Action): TransferState {
  switch (a.type) {
    case 'amountChanged': return s.step === 'edit' ? { ...s, amount: a.value, error: undefined } : s;
    case 'review': {
      if (s.step !== 'edit') return s;
      const n = Number(s.amount);
      return Number.isFinite(n) && n > 0 ? { step: 'confirm', amount: n } : { ...s, error: 'Enter a valid amount' };
    }
    case 'submit': return s.step === 'confirm' ? { step: 'submitting', amount: s.amount } : s;   // ignores double submits
    case 'succeeded': return { step: 'done', reference: a.reference };
    case 'back': return s.step === 'confirm' ? { step: 'edit', amount: String(s.amount) } : s;
  }
}
