export function AccountDetails({ accountId }: { accountId: string }) {
  const [account, setAccount] = useState<Account | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    setAccount(null); setError(null);
    fetch('/bff/api/accounts/' + accountId, { signal: controller.signal, credentials: 'include' })
      .then(r => (r.ok ? r.json() : Promise.reject(new Error('HTTP ' + r.status))))
      .then(setAccount)
      .catch(e => { if (e.name !== 'AbortError') setError('Could not load account'); });
    return () => controller.abort();                          // previous request cancelled when accountId changes
  }, [accountId]);

  if (error) return <p role="alert">{error}</p>;
  return account ? <AccountView account={account} /> : <Skeleton />;
}

// Stale closure fix with functional update
useEffect(() => {
  const id = setInterval(() => setSecondsLeft(s => Math.max(0, s - 1)), 1000);   // no dependency on secondsLeft needed
  return () => clearInterval(id);
}, []);
