// Domain hook: session timeout warning for banking (idle detection, warning, extension)
export function useSessionTimeout({ idleMs, warnMs, onExpire }: { idleMs: number; warnMs: number; onExpire: () => void }) {
  const [secondsLeft, setSecondsLeft] = useState<number | null>(null);
  const lastActivity = useRef(Date.now());
  const onExpireRef = useRef(onExpire);
  useEffect(() => { onExpireRef.current = onExpire; }, [onExpire]);       // latest callback without re-subscribing

  useEffect(() => {
    const touch = () => { lastActivity.current = Date.now(); setSecondsLeft(null); };
    const events = ['pointerdown', 'keydown'] as const;
    events.forEach(e => window.addEventListener(e, touch, { passive: true }));
    const id = setInterval(() => {
      const idle = Date.now() - lastActivity.current;
      if (idle >= idleMs) { clearInterval(id); onExpireRef.current(); }
      else if (idle >= idleMs - warnMs) setSecondsLeft(Math.ceil((idleMs - idle) / 1000));
    }, 1000);
    return () => { clearInterval(id); events.forEach(e => window.removeEventListener(e, touch)); };
  }, [idleMs, warnMs]);

  const extend = useCallback(() => { lastActivity.current = Date.now(); setSecondsLeft(null); }, []);
  return { secondsLeft, warning: secondsLeft !== null, extend };
}
