// External store: price feed outside React with immutable snapshots
class PriceStore {
  private snapshot: ReadonlyMap<string, number> = new Map();
  private listeners = new Set<() => void>();
  subscribe = (l: () => void) => { this.listeners.add(l); return () => this.listeners.delete(l); };
  getSnapshot = () => this.snapshot;                                // same reference until a change
  apply(ticks: { pair: string; mid: number }[]) {
    const next = new Map(this.snapshot);
    for (const t of ticks) next.set(t.pair, t.mid);
    this.snapshot = next;                                           // new immutable snapshot
    this.listeners.forEach(l => l());
  }
}
export const prices = new PriceStore();

export function usePrice(pair: string) {
  return useSyncExternalStore(
    prices.subscribe,
    () => prices.getSnapshot().get(pair),                           // selector returns a primitive: stable when unchanged
    () => undefined,                                                // server snapshot
  );
}

export function PriceCell({ pair }: { pair: string }) {
  const mid = usePrice(pair);
  return <td>{mid?.toFixed(5) ?? '-'}</td>;
}
