export function useRealtimeInvalidation() {
  const qc = useQueryClient();
  useEffect(() => {
    let source: EventSource | null = null;
    let retry = 0;
    let timer: ReturnType<typeof setTimeout>;
    const connect = () => {
      source = new EventSource('/bff/events', { withCredentials: true });
      source.onopen = () => {
        if (retry > 0) qc.invalidateQueries({ queryKey: ['payments'] });   // recover missed events after reconnect
        retry = 0;
      };
      source.addEventListener('payment-status', e => {
        const evt = JSON.parse((e as MessageEvent<string>).data) as { paymentId: string; accountId: string };
        qc.invalidateQueries({ queryKey: ['payments'] });
        qc.invalidateQueries({ queryKey: ['accounts'] });                    // balances refetched with authorisation
      });
      source.onerror = () => {
        source?.close();
        const delay = Math.min(30000, 500 * 2 ** retry++) + Math.random() * 300;
        timer = setTimeout(connect, delay);
      };
    };
    connect();
    return () => { clearTimeout(timer); source?.close(); };
  }, [qc]);
}
