// Session and step-up handling in the React shell
export function useApi() {
  return async function call<T>(path: string, init?: RequestInit): Promise<T> {
    const res = await fetch('/bff/api' + path, { ...init, credentials: 'include', headers: { 'X-CSRF': '1', 'Content-Type': 'application/json', ...init?.headers } });
    if (res.status === 401) {
      const challenge = res.headers.get('X-Step-Up');                  // e.g. "acr=urn:bank:sca"
      const returnUrl = encodeURIComponent(location.pathname + location.search);
      location.assign(challenge ? '/bff/login?acr=' + encodeURIComponent(challenge) + '&returnUrl=' + returnUrl : '/bff/login?returnUrl=' + returnUrl);
      throw new Error('redirecting');
    }
    if (!res.ok) throw await ApiError.from(res);
    return res.json() as Promise<T>;
  };
}
