export function useAssistantStream() {
  const [text, setText] = useState('');
  const [streaming, setStreaming] = useState(false);
  const controllerRef = useRef<AbortController | null>(null);
  const buffer = useRef('');

  const ask = useCallback(async (question: string) => {
    controllerRef.current?.abort();
    const controller = new AbortController(); controllerRef.current = controller;
    setText(''); buffer.current = ''; setStreaming(true);
    let frame = 0;
    try {
      const res = await fetch('/bff/assistant/stream', { method: 'POST', credentials: 'include', signal: controller.signal,
        headers: { 'Content-Type': 'application/json', 'X-CSRF': '1' }, body: JSON.stringify({ question }) });
      const reader = res.body!.pipeThrough(new TextDecoderStream()).getReader();
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer.current += value;
        if (!frame) frame = requestAnimationFrame(() => { setText(buffer.current); frame = 0; });   // batch per frame
      }
      setText(buffer.current);
    } finally { setStreaming(false); }
  }, []);

  return { text, streaming, ask, cancel: () => controllerRef.current?.abort() };
}
